		fromfrom = {
			# Wipe armies
			every_planet_army = {
				remove_army = yes
			}
			set_variable = { #math out growth gain
				which = pops_devoured
				value = 0
			}
			export_trigger_value_to_variable = {
				trigger = count_owned_pop_amount
				variable = pops_devoured
				rounded = yes
			}
			divide_variable = {
				which = pops_devoured
				value = 100 #1 per 100 pops
